if (this.getProperty("name") == "Suppress in hook")
{
    this.setAttribute("version", "0");
    this.setProperty("note", "Suppressed by source");
}
if (this.getProperty("name") == "Temporary preflight" &&
    String.IsNullOrEmpty(this.getAttribute("oldId")))
{
    this.setProperty("name", "Preflight only");
}
if (this.getProperty("name") == "Reject preflight" &&
    String.IsNullOrEmpty(this.getAttribute("oldId")))
{
    return this.getInnovator().newError("Reference preflight rejected");
}
if (this.getProperty("name") == "Reject reentry" &&
    !String.IsNullOrEmpty(this.getAttribute("oldId")))
{
    return this.getInnovator().newError("Reference reentry rejected");
}
return this;

