var inn = this.getInnovator();
var edit = inn.newItem("RefDocument", "edit");
edit.setID(this.getID());
edit.setProperty("name", "Submitted");
var saved = edit.apply();
var promotion = inn.newItem("RefDocument", "promoteItem");
promotion.setID(saved.getID());
promotion.setProperty("state", "Blocked");
return promotion.apply();

var inn = this.getInnovator();
var first = inn.newItem("RefPlain", "edit");
first.setID(this.getProperty("plain"));
first.setProperty("name", "Earlier write");
first.apply();
try
{
    var second = inn.newItem("RefDocument", "edit");
    second.setID(this.getID());
    second.setProperty("name", "Reject");
    second.apply();
}
catch (Exception)
{
    // A native comparison must determine the owning transaction outcome.
}
return inn.newResult("Caught nested failure");

