}
foreach (string id in eventData.NewItemsIds)
{
    var query = this.newItem("RefBatch", "get");
    query.setID(id);
    var current = query.apply();
    if (current.isError()) { return current; }
    if (current.getProperty("name") == "Reject")
    {
        return this.getInnovator().newError("Reference collection rejected");
    }
}
return this;

